('2302fce9-4754-5ca2-9ee9-436b64e257fb','84545cec-b526-552a-887c-1817e59fab0f','improvement','Trọng tâm cải thiện: Chủ động trao đổi sớm hơn khi gặp điểm nghẽn kỹ thuật','Trong 30 ngày đầu, Trần Gia Huy cần luyện tập có phản hồi để chủ động trao đổi sớm hơn khi gặp điểm nghẽn kỹ thuật.',80,'high','{"action":"follow_roadmap","direction":"Kỹ sư phần mềm backend","duration_days":90}','active','2026-08-25 18:07:00.000000'),
